=== ZimmButton prop surface ===
8:// large/medium) → Chakra variant/size names that zimmButton.css.ts recognises.
10:type ZimmButtonBaseProps = {
11:  /** Visible label (primary/secondary) or aria-label (icon variant — no visible text). */
12:  label: string;
18:   * reader users can never reach it to hear why the action is unavailable. `onClick` is
20:   * unavailable-but-explainable states (e.g. Add to Bag with an out-of-stock size selected).
27:  onClick?: () => void;
34:  variant?: 'primary' | 'secondary' | 'social';
36:   *  (same responsive size as the social variant, applied to primary/secondary colours). */
37:  size?: 'large' | 'medium' | 'adaptive';
38:  fullWidth?: boolean;
41:  /** Optional icon rendered before the label. Pass a ZimmIcon or any React node. */
43:  /** Optional icon rendered after the label. Pass a ZimmIcon or any React node. */
48:  variant: 'icon';
50:  /** Icon render size — one of the iconSizes keys ('sm' | 'md' | 'lg'). Defaults to 'md' (16px). */
51:  size?: ZimmIconSize;
54:type ZimmButtonProps = ZimmLabelButtonProps | ZimmIconButtonProps;
58:/** Atom — labelled button (primary/secondary) or icon-only button. All visual states
60: *  Labelled variants accept optional `iconLeading` and `iconTrailing` nodes rendered either
61: *  side of the label; gap between icon and text is set by the button's flex gap in baseStyle. */
63:  const { label, type = 'button', disabled = false, ariaDisabled = false, inverse = false, onClick, style, sx } = props;
