/** @type {import('../buildTemplate').ContentTypeDefinition} */
module.exports = {
  id: 'uiCopy',
  name: 'UI Copy',
  displayField: 'title',
  description:
    'One entry per UI string (error text, input placeholders, CTA labels, etc.). ' +
    'Fetched in bulk — all entries of this type, one CDA call per locale — and assembled ' +
    'into a key→value lookup map at runtime. Adding a new string never requires a schema change.',
  fields: [
    {
      id: 'title',
      name: 'Title',
      type: 'Symbol',
      required: true,
      localized: false,
      // Editor-facing friendly name (e.g. "Footer — Subscribe Button Label") — never rendered
      // in the app. Purely so Studio's entry list is scannable instead of showing the raw
      // dot-path key. Same role as footerConfig's internalTitle.
    },
    {
      id: 'key',
      name: 'Key',
      type: 'Symbol',
      required: true,
      localized: false,
      // The lookup identifier (e.g. checkout.submitButton). Must be identical across
      // locales to work as a map key, hence not localized.
      validations: [{ unique: true }],
    },
    {
      id: 'value',
      name: 'Value',
      type: 'Symbol',
      required: true,
      localized: true,
    },
    {
      id: 'description',
      name: 'Description',
      type: 'Text',
      required: false,
      localized: false,
      // Translator/editor context — not localized (it's a note about the string, not
      // itself translated). Translators working key-by-key in Transperfect can't see
      // the string in situ on the page.
    },
  ],
};

